      select(options,'Mapped places','corridorPlaces',[['urban','Cities / towns'],['place','Cities / towns / villages']],state.places,v=>{state.places=v;setPreset(name,{keepContext:true}).then(()=>{el('connectivityOptions').open=true;el('corridorPlaces')?.focus({preventScroll:true});});});
